from itertools import combinations
from math import comb, floor
from typing import List, Set, Tuple, FrozenSet

Edge = FrozenSet[int]

def turan_edge_bound_real(n: int, r: int) -> float:
    return (1.0 - 1.0 / r) * n * n / 2.0

def turan_graph_edges(n: int, r: int) -> int:
    sizes: List[int] = [n // r + (1 if i < n % r else 0) for i in range(r)]
    return comb(n, 2) - sum(comb(s, 2) for s in sizes)

def complete_bipartite(a: int, b: int) -> Tuple[int, Set[Edge]]:
    edges: Set[Edge] = {frozenset((u, v)) for u in range(a)
                        for v in range(a, a + b)}
    return (a + b, edges)

def triangle_count(g: Tuple[int, Set[Edge]]) -> int:
    n, E = g
    return sum(1 for a, b, c in combinations(range(n), 3)
               if frozenset((a, b)) in E and frozenset((a, c)) in E
               and frozenset((b, c)) in E)

for n in (8, 12, 16):
    for r in (2, 3, 4):
        bound, achieved = turan_edge_bound_real(n, r), turan_graph_edges(n, r)
        assert achieved <= bound + 1e-9
        print(f'n={n} r={r}: bound={bound:.2f} T(n,r) edges={achieved}')

for n in (6, 8, 10):
    g = complete_bipartite(n // 2, n - n // 2)
    e = len(g[1])
    assert triangle_count(g) == 0 and e == floor(n * n / 4)
    print(f'Mantel n={n}: edges={e} = floor(n^2/4), triangle-free')

from itertools import combinations
from typing import FrozenSet

def is_three_ap_free(s: FrozenSet[int]) -> bool:
    for b in s:
        for a in s:
            if a != b and (2 * b - a) in s and (2 * b - a) != b:
                return False
    return True

def roth_number(n: int) -> int:
    for size in range(n, 0, -1):
        for combo in combinations(range(n), size):
            if is_three_ap_free(frozenset(combo)):
                return size
    return 0

for n in range(1, 18):
    r3 = roth_number(n)
    print(f'N={n:2d}: r_3(N)={r3:2d}  density={r3 / n:.3f}')

