function TURAN_EDGES(n, r):
    sizes <- empty list
    for i in 0 .. r-1:
        sizes[i] <- floor(n / r) + (1 if i < (n mod r) else 0)
    within <- sum over i of C(sizes[i], 2)
    return C(n, 2) - within

function SHADOW(family):
    out <- empty set
    for s in family:
        for x in s:
            out.add(s without x)
    return out

function ITERATED_SHADOW(family, i):
    cur <- family
    repeat i times:
        cur <- SHADOW(cur)
    return cur

