function TRIANGLE_COUNT(G):
    t <- 0
    for each triple {a,b,c} of vertices:
        if a~b and a~c and b~c: t <- t + 1
    return t

function DICHOTOMY_BRANCH(G, n, delta, epsilon):
    t <- TRIANGLE_COUNT(G)
    if t >= delta * n^3: return 'supersaturated (>= delta*n^3 triangles)'
    else: return 'edge-close to triangle-free (removable < epsilon*n^2)'

